def parse_duration(s: str) -> int:
    import re
    m = re.match(r"(\d+)([a-z]+)", s)
    if m:
        num, unit = m.groups()
        num = int(num)
        if unit == "s":
            return num
        elif unit == "m":
            return num * 60
        elif unit == "h":
            return num * 3600
    raise ValueError("Invalid duration format")
